preConditionHook:
// THE TREND LINE, one construction shared by the whole lines/channels family
// (decided in slice B01, carried here unchanged): the BULL trend line runs
// through the two most recent CONFIRMED swing LOWS, the BEAR trend line through
// the two most recent confirmed swing HIGHS; the two lines are deliberately NOT
// parallel. The pivot scan is INLINED rather than reaching into SwingHigh.json
// -- rules in this corpus never reference each other -- and mirrors the EL
// twin's SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and
// 2.
//
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR ABOVE the swingStrength OLDER bars, STRICTLY ABOVE the
// swingStrength NEWER bars -- so a flat top yields exactly one pivot, the later
// of the equal bars; bars-ago indexing makes the SMALLER index the NEWER bar,
// so the strict half is the k < j loop. The confirmation lag is exactly
// swingStrength bars, never 0 or 1, which is what makes the scan lookahead-safe;
// pivotLookback is EL's Length (candidate offsets 0..pivotLookback-1 from the
// current bar inclusive) and the neighbourhood test reaches swingStrength bars
// PAST the window, so the deepest index the scan touches is
// pivotLookback - 1 + swingStrength; a window with no pivot returns the -1
// SENTINEL, guarded below because -1 as a price sits under every real price;
// Occurrence 3+ is UNMEASURED and is never asked for; the comparisons carry the
// 2.22e-12 relational tolerance, hence el_gt / el_ge. The low side's tie sense
// is the mirror of the measured high-side rule. No WFSafe_SwingHigh exists, so
// plain EL governs.
//
// MEASURED, EL_TLValue_Probe.txt: TLValue is the pure two-point line
// Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) * Slope, anchored
// at the FIRST pair and extrapolating freely past both anchors -- which is what
// lets the line be read at an OLDER bar inside the loop below. Bars-ago is the
// convention here, so the OLDER pivot (the LARGER bars-ago) is P1/B1, the
// zero-drift spelling. Bar1 = Bar2 silently returns 0.0, so B1 != B2 is
// guarded. The slope is hoisted out of the per-target arithmetic where the EL
// twin recomputes it inside each TLValue call; identical doubles, same line.
//
// THIS RULE: Brooks's single most repeated rule, the standing permission for a
// countertrend entry -- never trade against a trend until its trend line has
// broken. At least minBreaks bars in the last withinBars CLOSED through the
// line. Distinct from a break rule that fires only on the break bar: this stays
// true for a window afterwards, which is what all thirteen sources want.
//
// A LONG needs the BEAR trend line (across the swing HIGHS) to have been closed
// through from below; a SHORT needs the BULL trend line (across the swing LOWS)
// to have been closed through from above. That is the opposite pairing from
// TrendLineTouch, which is a WITH-trend pullback and reads the line on its own
// side.
//
// THE PIVOTS ARE THE CURRENT ONES, not the pivots as they stood at bar kk.
// Re-deriving the pivot set per bar of the window is not expressible in EL, so
// the line is re-read at each bar of the window through TLValue's free
// extrapolation, exactly as ChannelLineBreakoutFailure does -- the same
// simplification made the same way in both twins.
//
// Counted with an explicit loop rather than CountIF: CountIF's argument is a
// price SERIES and the counted predicate compares against a line whose value is
// different on every bar of the window.
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// Every one is fully assigned each bar before it is read.
pivS = (int)swingStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
upBreaks = 0;
dnBreaks = 0;
for (int kk = 0; kk <= (int)withinBars - 1; ++kk) {
    if (haveHiLine && el_gt(close[kk], hiP1 + ((double)kk - hiB1) * hiSlope)) ++upBreaks;
    if (haveLoLine && el_lt(close[kk], loP1 + ((double)kk - loB1) * loSlope)) ++dnBreaks;
}
